(function () {
  function text(v) {
    return v == null ? '' : String(v);
  }
  function pick() {
    for (var i = 0; i < arguments.length; i++) {
      var v = arguments[i];
      if (v != null && String(v) !== '') return String(v);
    }
    return '';
  }
  function pad(n) { return n < 10 ? '0' + n : String(n); }
  function nowText() {
    var d = new Date();
    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate())
      + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
  }

  var data = $.data || {};
  var patient = data.patientInfo || {};
  var sheet = data.chagPatientSheet || {};
  var details = data.chagPatientSheetDetail || [];
  if (!Array.isArray(details) || details.length === 0) {
    throw new Error('账单明细为空');
  }

  var confirmTime = nowText();
  var visitNumber = text(patient.visitNo);
  var presId = pick(sheet.presId, sheet.settlementOrderNo, sheet.idPatientSheet);
  var orders = [];
  var hisItems = [];
  var seen = {};
  for (var i = 0; i < details.length; i++) {
    var item = details[i] || {};
    var orderId = pick(item.hisDetailId, item.presId, item.firstHisDetailId, item.previousHisDetailId, sheet.presId, item.applyId, item.idPatientFeeItem);
    if (!orderId) {
      throw new Error('缺少医嘱编码 orderId');
    }
    hisItems.push({
      idPatientFeeItem: item.idPatientFeeItem,
      hisDetailId: orderId
    });
    if (seen[orderId]) continue;
    seen[orderId] = true;
    orders.push({
      applId: text(item.applyId),
      orderId: orderId,
      visitNumber: visitNumber,
      departmentId: '66fca4551d3a1d0001fab02d',
      confirmTime: confirmTime,
      userId: '6a4db0dc4da7fc0001a9609a',
      directId: '-1',
      visitTypeCode: '114',
      organizationId: '66fca42db0c0ad0001f1a9f4',
      applicationDepartmentId: '0921',
      accountId: '66fca570063ef80001a5da41',
      mainInsurancePlanId: null,
      sender: 'HELIAN-TJ',
      applicationEmployeeId: 'XT_HLJK_TJ',
      tenantId: 'GHIS'
    });
  }
  return {
    orders: orders,
    hisItems: hisItems,
    presId: presId || null,
    timestamp: String(Date.now())
  };
})()

(function () {
  function collect(node, codes, statusHolder, detailHolder, depth) {
    if (node == null || depth > 6) return;
    if (typeof node === 'string') {
      var text = node.trim();
      if (!text) return;
      try { collect(JSON.parse(text), codes, statusHolder, detailHolder, depth + 1); }
      catch (e) { if (!detailHolder.v) detailHolder.v = text; }
      return;
    }
    if (typeof node !== 'object') return;
    if (node.code != null && node.code !== '') codes.push(String(node.code));
    if (node.status != null) statusHolder.v = node.status;
    if (node.detail) detailHolder.v = node.detail;
    else if (node.msg && !detailHolder.v) detailHolder.v = node.msg;
    else if (node.message && !detailHolder.v) detailHolder.v = node.message;
    if (node.encryptData != null) collect(node.encryptData, codes, statusHolder, detailHolder, depth + 1);
    if (node.body != null) collect(node.body, codes, statusHolder, detailHolder, depth + 1);
    if (node.data != null && typeof node.data === 'object') collect(node.data, codes, statusHolder, detailHolder, depth + 1);
  }
  var codes = [];
  var statusHolder = { v: null };
  var detailHolder = { v: '' };
  collect($.body, codes, statusHolder, detailHolder, 0);
  var ok = codes.length > 0
    && codes.every(function (c) { return c === '200' || c === '0'; })
    && (statusHolder.v == null || statusHolder.v === true);
  return {
    code: ok ? '200' : '-1',
    message: ok ? '删除成功' : (detailHolder.v || '失败'),
    rsp: {
      presId: $.presId || null,
      hisItems: $.hisItems || []
    }
  };
})()
